27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 format")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "postcode")
55	    private String postcode;
56	
57	    @Column(name = "registration_date")
58	    private LocalDate registrationDate;
59	
60	    @Column(name = "customer_code")
61	    private String customerCode;
62	
63	    @Column(name = "household_id")
64	    private String householdId;
65	
66	    @Column(name = "namesake_count")
67	    private Integer namesakeCount;
68	
69	    @Column(name = "household_size")
70	    private Integer householdSize;
71	
72	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
73	    private Set<Pet> pets;
74	
75	    public String getAddress() {
76	        return this.address;
77	    }
78	
79	    public void setAddress(String address) {
80	        this.address = address;
81	    }
82	
83	    public String getCity() {
84	        return this.city;
85	    }
86	
87	    public void setCity(String city) {
88	        this.city = city;
89	    }
90	
91	    public String getTelephone() {
92	        return this.telephone;
93	    }
94	
95	    public void setTelephone(String telephone) {
96	        this.telephone = telephone;
97	    }
98	
99	    public String getEmail() {
100	        return this.email;
101	    }
102	
103	    public void setEmail(String email) {
104	        this.email = email;
105	    }
106	
107	    public String getPostcode() {
108	        return this.postcode;
109	    }
110	
111	    public void setPostcode(String postcode) {
112	        this.postcode = postcode;
113	    }
114	
115	    public LocalDate getRegistrationDate() {
116	        return this.registrationDate;
117	    }
118	
119	    public void setRegistrationDate(LocalDate registrationDate) {
120	        this.registrationDate = registrationDate;
121	    }
122	
123	    public String getCustomerCode() {
124	        return this.customerCode;
125	    }
126	
127	    public void setCustomerCode(String customerCode) {
128	        this.customerCode = customerCode;
129	    }
130	
131	    public String getHouseholdId() {
132	        return this.householdId;
133	    }
134	
135	    public void setHouseholdId(String householdId) {
136	        this.householdId = householdId;
137	    }
138	
139	    public Integer getNamesakeCount() {
140	        return this.namesakeCount;
141	    }
142	
143	    public void setNamesakeCount(Integer namesakeCount) {
144	        this.namesakeCount = namesakeCount;
145	    }
146	
147	    public Integer getHouseholdSize() {
148	        return this.householdSize;
149	    }
150	
151	    public void setHouseholdSize(Integer householdSize) {
152	        this.householdSize = householdSize;
153	    }
154	
155	    /**
156	     * The owner's identity key: the single derived value used to detect duplicate owners, formed
157	     * as {@code normalizedTelephone + '|' + email + '|' + householdId} where an absent telephone,
158	     * email or household contributes an empty string. Two owners are duplicates only when their
159	     * whole identity keys are equal, so housemates that share a {@code householdId} but hold
160	     * different telephones have distinct identity keys and are both allowed.
161	     */
162	    public String getIdentityKey() {
163	        return orEmpty(this.telephone) + "|" + orEmpty(this.email) + "|" + orEmpty(this.householdId);
164	    }
165	
166	    private static String orEmpty(String value) {
167	        return value == null ? "" : value;
168	    }
169	
170	    /**
171	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY is the
172	     * last two digits of the registration date's year (e.g. {@code 'SMI-0007-M26'}). Derived
173	     * from the owner's own fields; absent until both the customer code and registration date
174	     * have been assigned.
175	     */
176	    public String getMembershipNumber() {
177	        if (this.customerCode == null || this.registrationDate == null) {
178	            return null;
179	        }
180	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
181	    }
182	
183	    /**
184	     * The owner's check digit: a single Luhn check digit (0-9) computed over the digits of the
185	     * {@link #getCustomerCode() customer code}. Absent until the customer code has been assigned.
186	     */
187	    public Integer getCheckDigit() {
188	        if (this.customerCode == null) {
189	            return null;
190	        }
191	        return Luhn.checkDigit(this.customerCode);
192	    }
193	
194	    /**
195	     * The owner's membership level, a number from 1 to 3 derived from the owner's own fields:
196	     * every owner starts at level 1, gains a level when an email address is present, and gains a
197	     * further level when this owner has no namesakes ({@code namesakeCount} is 0). The result is
198	     * capped at 3; level 4 is reserved for tenure.
199	     */
200	    public Integer getMembershipLevel() {
201	        int level = 1;
202	        boolean hasEmail = this.email != null && !this.email.isEmpty();
203	        if (hasEmail) {
204	            level++;
205	        }
206	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
207	        if (unique) {
208	            level++;
209	        }
210	        return Math.min(level, 3);
211	    }
212	
213	    /**
214	     * The owner's locality: the REGION segment of the {@link #getCustomerCode() customer code} (the
215	     * region derived from the postcode when the identity was assigned), or {@link Regions#UNKNOWN}
216	     * before a customer code has been assigned.
217	     */
218	    public String getLocality() {
219	        if (this.customerCode == null) {
220	            return Regions.UNKNOWN;
221	        }
222	        int separator = this.customerCode.indexOf('-');
223	        return separator < 0 ? this.customerCode : this.customerCode.substring(0, separator);
224	    }
225	
226	    /**
227	     * The owner's preferred contact channel, derived from the owner's own fields:
228	     * {@code "EMAIL"} when an {@link #getEmail() email} is present, otherwise {@code "PHONE"}.
229	     */
230	    public String getContactPreference() {
231	        boolean hasEmail = this.email != null && !this.email.isEmpty();
232	        return hasEmail ? "EMAIL" : "PHONE";
233	    }
234	
235	    /**
236	     * Resolve the effective registration date before persisting: default it to the server's
237	     * current date when none was supplied, then roll it forward off weekends so a newly
238	     * registered owner always has a business-day registration date. Every value derived from it
239	     * (such as the {@link #getMembershipNumber() membership number}) therefore uses the adjusted
240	     * date.
241	     */
242	    @PrePersist
243	    private void resolveRegistrationDate() {
244	        if (this.registrationDate == null) {
245	            this.registrationDate = LocalDate.now();
246	        }
247	        this.registrationDate = BusinessDay.onOrAfter(this.registrationDate);
248	    }
249	
250	    protected Set<Pet> getPetsInternal() {
251	        if (this.pets == null) {
252	            this.pets = new HashSet<>();
253	        }
254	        return this.pets;
255	    }
256	
257	    protected void setPetsInternal(Set<Pet> pets) {
258	        this.pets = pets;
259	    }
260	
261	    public List<Pet> getPets() {
262	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
263	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
264	        return Collections.unmodifiableList(sortedPets);
265	    }
266	
267	    public void setPets(List<Pet> pets) {
268	        this.pets = new HashSet<>(pets);
269	    }
270	
271	    public void addPet(Pet pet) {
272	        getPetsInternal().add(pet);
273	        pet.setOwner(this);
274	    }
275	
276	    /**
277	     * Return the Pet with the given name, or null if none found for this Owner.
278	     *
279	     * @param name to test
280	     * @return true if pet name is already in use
281	     */
282	    public Pet getPet(String name) {
283	        return getPet(name, false);
284	    }
285	
286	    /**
287	     * Return the Pet with the given name, or null if none found for this Owner.
288	     *
289	     * @param name to test
290	     * @return true if pet name is already in use
291	     */
292	    public Pet getPet(String name, boolean ignoreNew) {
293	        name = name.toLowerCase();
294	        for (Pet pet : getPetsInternal()) {
295	            if (!ignoreNew || !pet.isNew()) {
296	                String compName = pet.getName();
297	                compName = compName.toLowerCase();
298	                if (compName.equals(name)) {
299	                    return pet;
300	                }
301	            }
302	        }
303	        return null;
304	    }
305	
306	    public Pet getPet(Integer petId) {
307	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
308	    }
309	
310	    @Override
311	    public String toString() {
312	        return new ToStringCreator(this)
313	
314	            .append("id", this.getId())
315	            .append("new", this.isNew())
316	            .append("lastName", this.getLastName())
317	            .append("firstName", this.getFirstName())
318	            .append("address", this.address)
319	            .append("city", this.city)
320	            .append("telephone", this.telephone)
321	            .append("email", this.email)
322	            .toString();
