/**
 * Thrown when an owner is created in a city that already holds the maximum permitted number of
 * owners. Carries the conflicting city so the REST layer can report what was rejected.
 */
public class CityOwnerLimitExceededException extends RuntimeException {

    private final String city;

    public CityOwnerLimitExceededException(String city) {
        super("The city '" + city + "' already has the maximum number of owners");
        this.city = city;
