package org.springframework.samples.petclinic.rest.error;

import java.time.LocalDate;

/**
 * Thrown when an owner is created with a supplied registration date later than the server's current
 * date. Carries the rejected date so the REST layer can report what was rejected.
 */
public class FutureRegistrationDateException extends RuntimeException {

    private final LocalDate registrationDate;

    public FutureRegistrationDateException(LocalDate registrationDate) {
        super("The registration date '" + registrationDate + "' is later than the current date");
        this.registrationDate = registrationDate;
    }

    public LocalDate getRegistrationDate() {
        return this.registrationDate;
    }
}

